<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import type {TripRecord,TripWorkCandidate,TripWorkFact} from '~~/shared/types/diagnostic-trips';
import {tripDateLabel} from '~~/shared/utils/diagnostic-trips';
import TripDateInput from './TripDateInput.vue';
const props=defineProps<{trip:TripRecord}>();const emit=defineEmits<{close:[];saved:[TripRecord]}>();
const rows=ref<TripWorkCandidate[]>([]),facts=ref<Record<string,TripWorkFact>>({}),selected=ref<string[]>([]),query=ref(''),loading=ref(false),busy=ref(false),error=ref(''),onlyTrip=ref(false);
const key=(w:TripWorkCandidate)=>w.kind+':'+w.id;
const filtered=computed(()=>rows.value.filter(w=>[w.name,w.structureCode,w.planExecutor].join(' ').toLocaleLowerCase('ru').includes(query.value.toLocaleLowerCase('ru'))));
async function load(){loading.value=true;error.value='';try{rows.value=await $fetch<TripWorkCandidate[]>('/api/diagnostic/trips/'+props.trip.id+'/works');facts.value=Object.fromEntries(rows.value.map(w=>[key(w),{id:w.id,kind:w.kind,version:w.version,start:w.factStart||props.trip.start,finish:w.factFinish||props.trip.finish,hours:w.factHours??'',executorId:props.trip.participants.find(p=>p.name===w.factExecutor)?.id??0}]));selected.value=[];}catch(e:any){error.value=e?.data?.message||'Не удалось загрузить работы.';}finally{loading.value=false;}}
onMounted(load);
async function save(){if(!selected.value.length&&!onlyTrip.value)return;busy.value=true;error.value='';try{const r=await $fetch<TripRecord>('/api/diagnostic/trips/'+props.trip.id+'/close',{method:'POST',headers:{'x-space-diagnostic':'1'},body:{version:props.trip.version,works:selected.value.map(k=>facts.value[k])}});emit('saved',r);}catch(e:any){error.value=e?.data?.message||'Не удалось закрыть командировку.';}finally{busy.value=false;}}
</script>
<template>
 <UModal :open="true" :title="`Закрытие командировки ${trip.number}`" :ui="{content:'odis-trip-modal w-[96vw] sm:max-w-none h-[88dvh]',header:'trip-modal-header',body:'trip-modal-body',footer:'trip-modal-footer'}" @update:open="v=>{if(!v&&!busy)emit('close')}">
  <template #body><p class="trip-notice">{{trip.contractNumber}} · {{tripDateLabel(trip.start)}} — {{tripDateLabel(trip.finish)}}. Выберите выполненные работы и укажите факт. Остальные работы останутся без изменений.</p><p class="trip-notice">В списке — незавершённые работы договора и выбранных сооружений. Принадлежность к этой поездке подтвердите выбором.</p><div class="trip-bar"><label>Поиск работы<input v-model="query" placeholder="Название, ИССО, исполнитель"/></label><strong>Выбрано: {{selected.length}}</strong></div>
   <div class="trip-table-scroll trip-close-table"><table><thead><tr><th></th><th>Работа / ИССО</th><th>План, чел·ч</th><th>Начало, факт</th><th>Окончание, факт</th><th>Факт, чел·ч</th><th>Исполнитель, факт</th></tr></thead><tbody><tr v-if="loading"><td colspan="7">Загрузка работ…</td></tr><tr v-for="w in filtered" :key="key(w)"><td><input v-model="selected" type="checkbox" :value="key(w)" :disabled="busy" :aria-label="`Закрыть работу ${w.name}`"/></td><td>{{w.name}}<small>{{w.structureCode?'ИССО: '+w.structureCode:'Работа с договором'}} · {{w.planExecutor||'Исполнитель не назначен'}}</small><small v-if="w.factStart||w.factFinish||w.factHours!=null||w.factExecutor">Текущий факт: {{tripDateLabel(w.factStart)}} — {{tripDateLabel(w.factFinish)}}, {{w.factHours??'—'}} чел·ч · {{w.factExecutor||'Исполнитель не указан'}}</small></td><td>{{w.planHours??'—'}}</td><td><TripDateInput v-model="facts[key(w)]!.start" :disabled="busy||!selected.includes(key(w))"/></td><td><TripDateInput v-model="facts[key(w)]!.finish" :disabled="busy||!selected.includes(key(w))"/></td><td><input v-model="facts[key(w)]!.hours" :disabled="busy||!selected.includes(key(w))" inputmode="decimal" placeholder="0"/></td><td><select v-model.number="facts[key(w)]!.executorId" :disabled="busy||!selected.includes(key(w))"><option :value="0">Выберите участника</option><option v-for="p in trip.participants" :key="p.id" :value="p.id">{{p.name}}</option></select></td></tr><tr v-if="!loading&&!filtered.length"><td colspan="7">Доступных работ по заданным условиям нет.</td></tr></tbody></table></div>
   <label v-if="!selected.length" class="trip-inline-check"><input v-model="onlyTrip" type="checkbox" :disabled="busy"/>Закрыть только командировку, без изменения работ</label><p v-if="error" class="trip-error" role="alert">{{error}} <button v-if="!rows.length" @click="load">Повторить загрузку</button></p>
  </template><template #footer><div class="trip-footer"><span>Изменения сохраняются совместно.</span><div><button class="trip-primary" :disabled="loading||busy||(!selected.length&&!onlyTrip)" @click="save">{{busy?'Сохранение…':'Закрыть командировку'}}</button><button :disabled="busy" @click="emit('close')">Отменить</button></div></div></template>
 </UModal>
</template>
